INSERT OR IGNORE INTO material_catalog (id,curricular_unit_id,lesson_id,material_kind,bibliography_format,title,description,file_name,mime_type,storage_backend,storage_key,storage_state,byte_size,checksum_sha256,verification_status,publication_status,public_access,source_id,page_note,version_group,version_number,is_recommended,created_at,updated_at) SELECT 'material-biblio-2627-ap3-nolte7-translation',cu.id,'lesson-neuro-ap3','bibliography','translation','Nolte’s The Human Brain — AP3 · Tradução','Bibliografia traduzida para AP3 — Bolbo, protuberância e mesencéfalo. 45 páginas e 25 figuras.','AP3_Nolte_Bibliografia_Traduzida_2026-10-09.pdf','application/pdf','r2','materials/neuroanatomia/bibliografia/traducoes/2026-27/AP3_Nolte_Bibliografia_Traduzida_2026-10-09.pdf','ready',11212388,'d3243d070711ca596f1a28f40f4a2e4f9f682c2a717fecbdb580fbc69ec065a4','verified','published',0,'source-nolte-7','Nolte, 7.ª edição: pp. 272–295','biblio-2627-ap3-nolte7-translation',1,1,unixepoch()*1000,unixepoch()*1000 FROM curricular_units cu WHERE cu.code='NEURO' AND cu.active=1 AND EXISTS(SELECT 1 FROM material_sources WHERE id='source-nolte-7') AND EXISTS(SELECT 1 FROM material_lessons WHERE id='lesson-neuro-ap3');

