INSERT INTO admin_audit_log(actor_user_id,action,details,created_at) SELECT id,'neuro_translation_published','{"batch":"approved-ap3-nolte-2026-10-09"}',unixepoch()*1000 FROM users WHERE status='active' AND commission_position='principal_admin' AND NOT EXISTS(SELECT 1 FROM admin_audit_log WHERE action='neuro_translation_published' AND details LIKE '%approved-ap3-nolte-2026-10-09%') LIMIT 1;
